/* End-to-end client delivery process. Document records remain the source of truth. */
(function(){
const find=id=>db.documents.find(d=>d.id===id);
function related(q,type){return db.documents.find(d=>d.type===type&&d.status!=='Cancelled'&&(d.rootId===q.id||d.sourceId===q.id))}
function serviceDocument(q,type,index){return db.documents.find(d=>d.type===type&&d.status!=='Cancelled'&&d.rootId===q.id&&d.serviceIndex===index)}
function serviceProformas(q){return db.documents.filter(d=>d.type==='Proforma'&&d.status!=='Cancelled'&&d.rootId===q.id&&d.serviceIndex!==undefined)}
function stage(q){const p=related(q,'Proforma'),i=related(q,'Invoice');if(i&&totals(i).balance<=0)return 7;if(i)return 6;if(p&&totals(p).paid>=totals(p).total)return 5;if(p)return 4;if(q.contractConfirmedAt)return 3;if(q.status==='Accepted')return 2;if(q.status==='Sent')return 1;return 0;}
function reconcile(){let changed=false;for(const q of db.documents.filter(d=>d.type==='Quotation'&&d.clientApprovedForProcess&&d.contractConfirmedAt)){const before=db.documents.length;if(q.billingMode==='service-wise')ClientProcessEngine.prepareServiceProformas(db,q,uid);else ClientProcessEngine.prepare(db,q,uid);changed ||= before!==db.documents.length;}if(changed)persist();}
const names=['Quotation draft','Quotation sent','Quotation approved','Contract confirmed','50% advance due','Work in progress','Final payment due','Completed'];
function docActions(d){return `<button onclick="showPreview('${d.id}')">Preview</button><button onclick="openDoc('${d.id}')">Edit / payment</button><button onclick="processShare('${d.id}','whatsapp')">WhatsApp</button><button onclick="processShare('${d.id}','email')">Email</button>`;}
function receiptActions(d){return (d?.payments||[]).map((p,n)=>`<div class="totalrow"><span>Receipt · ${esc(p.date)} · ${esc(fmt(d,p.amount))}</span><span><button onclick="processShare('${d.id}','download',${n})">Download receipt</button><button onclick="processShare('${d.id}','whatsapp',${n})">WhatsApp</button><button onclick="processShare('${d.id}','email',${n})">Email</button></span></div>`).join('');}
function projectFor(q){return db.projects.find(project=>project.sourceQuotationId===q.id);}
function serviceBilling(q,project){
 const proformas=serviceProformas(q),lines=(q.items||[]).map((item,index)=>{
  const p=serviceDocument(q,'Proforma',index),invoice=serviceDocument(q,'Invoice',index),task=project?.tasks?.find(entry=>Number(entry.serviceIndex)===index),value=ClientProcessEngine.serviceValue(q,item),paid=p?(p.payments||[]).reduce((sum,payment)=>sum+num(payment.amount),0):0;
  const advanceReady=p&&paid+0.005>=totals(p).total,canInvoice=advanceReady&&task?.done&&!invoice;
  return `<article class="panel service-billing-card"><div class="dialog-title"><div><div class="eyebrow">SERVICE ${index+1}</div><h3>${esc(item.name||`Service ${index+1}`)}</h3><p class="sub">Quoted value ${esc(fmt(q,value))}${task?` · Work ${task.done?'completed':'in progress'}`:' · Add this service to the project work plan'}</p></div><span class="badge ${invoice&&totals(invoice).balance<=0?'Paid':p?'Sent':'Draft'}">${invoice?totals(invoice).balance<=0?'Paid':'Balance due':p?advanceReady?'Advance paid':'Advance due':'Proforma not created'}</span></div>${p?`<p><b>Proforma ${esc(p.number)}</b> · Advance ${esc(fmt(p,totals(p).total))} · Received ${esc(fmt(p,paid))} · Remaining ${esc(fmt(p,totals(p).balance))}</p><div class="actions">${docActions(p)}</div>${receiptActions(p)}`:'<p class="sub">A separate proforma will request this service’s 50% advance.</p>'}${canInvoice?`<button class="primary" onclick="processServiceBalance('${q.id}','${p.id}')">Prepare balance invoice</button>`:p&&!advanceReady?'<p class="hint">Record the full proforma advance before preparing the final balance invoice.</p>':p&&!task?'<p class="hint">Create the delivery project and add service tasks before issuing balance invoices.</p>':p&&task&&!task.done?'<p class="hint">Prepare the balance invoice when this service is complete in the project work plan.</p>':''}${invoice?`<h4>Balance invoice ${esc(invoice.number)} · Due ${esc(fmt(invoice,totals(invoice).balance))}</h4><div class="actions">${docActions(invoice)}</div>${receiptActions({...invoice,payments:(invoice.payments||[]).filter(payment=>!payment.sourceProformaId)})}`:''}</article>`;
 }).join('');
 return `<section class="panel service-billing"><div class="dialog-title"><div><div class="eyebrow">SERVICE-WISE BILLING</div><h2>Separate vouchers for each service</h2><p class="sub">Each service has its own 50% proforma, advance receipt, and balance invoice. Advances carry forward to the matching invoice.</p></div>${!proformas.length?'<button class="primary" onclick="processCreateServiceVouchers(\''+q.id+'\')">Create service proformas</button>':''}</div><div class="service-billing-list">${lines}</div></section>`;
}
window.processProject=id=>{const quotation=find(id);if(!quotation||!quotation.contractConfirmedAt)return toast('Confirm the contract before setting up delivery work.');let project=projectFor(quotation);if(!project){const client=db.clients.find(item=>item.id===quotation.clientId||item.email&&item.email===quotation.client?.email||item.phone&&item.phone===quotation.client?.phone||item.name===quotation.client?.name);const proforma=related(quotation,'Proforma'),proformas=serviceProformas(quotation),allAdvancesPaid=proformas.length===(quotation.items||[]).length&&proformas.every(item=>totals(item).paid>=totals(item).total),due=quotation.contract?.completionDate||quotation.due||'',deliveryMode=quotation.contract?.deliveryMode==='sequential'?'sequential':'parallel';project={id:uid(),sourceQuotationId:quotation.id,clientId:client?.id||'',name:quotation.project||`${quotation.client?.name||'Client'} project`,status:allAdvancesPaid||proforma&&totals(proforma).paid>=totals(proforma).total?'In progress':'Planned',budget:num(totals(quotation).total),due,notes:quotation.contract?.scope||quotation.project||'Services as quoted',deliveryMode,tasks:(quotation.items||[]).map((item,index)=>({id:uid(),title:`Deliver: ${item.name||'Service'}`,serviceIndex:index,sourceQuotationId:quotation.id,due,done:false,ownerId:'',ownerName:'',...(deliveryMode==='sequential'?{sequence:index+1}:{})})),milestones:[]};if(!commitChange(()=>db.projects.push(project),'Created delivery project '+project.name))return;}else{const proforma=related(quotation,'Proforma');if(project.deliveryMode!=='sequential'&&quotation.contract?.deliveryMode==='sequential')commitChange(()=>{project.deliveryMode='sequential';project.tasks=(project.tasks||[]).map((task,index)=>({...task,sequence:Number(task.sequence)||index+1}))},'Set project services to deliver one by one');if(proforma&&totals(proforma).paid>=totals(proforma).total&&project.status==='Planned')commitChange(()=>{project.status='In progress'},'Started delivery project '+project.name);}selectedProjectWorkspace=project.id;nav('Projects');};
window.processCreateServiceVouchers=id=>{const q=find(id);if(!q?.contractConfirmedAt)return toast('Confirm the contract before creating service proformas.');if(db.documents.some(d=>d.type==='Proforma'&&d.rootId===q.id&&d.status!=='Cancelled'&&d.serviceIndex===undefined))return toast('This quotation already has a combined proforma. Keep using that document to avoid duplicate advance requests.');let created=0;if(!commitChange(()=>{q.billingMode='service-wise';created=ClientProcessEngine.prepareServiceProformas(db,q,uid)},'Created separate service proformas for '+(q.client?.name||'client')))return;if(!created)toast('Separate service proformas already exist.');};
window.processServiceBalance=(quotationId,proformaId)=>{const q=find(quotationId),p=find(proformaId);if(!q||!p)return toast('The service billing record could not be found.');const project=projectFor(q),task=project?.tasks?.find(entry=>Number(entry.serviceIndex)===Number(p.serviceIndex));if(!task?.done)return toast('Mark this service complete in the project work plan before preparing its balance invoice.');if(totals(p).paid+0.005<totals(p).total)return toast('Record the full advance for this service before preparing the balance invoice.');const existing=serviceDocument(q,'Invoice',p.serviceIndex);if(existing)return openDoc(existing.id);let invoice=null;if(!commitChange(()=>{invoice=ClientProcessEngine.prepareServiceInvoice(db,q,p,uid)},'Prepared balance invoice for '+(p.serviceName||'service')))return;if(invoice)openDoc(invoice.id);};
window.clientProcessPage=()=>{reconcile();const quotes=db.documents.filter(d=>d.type==='Quotation'&&d.status!=='Cancelled');return pageHeader('Client process',`<button onclick="newDoc('Quotation')">+ New quotation</button><button onclick="refreshWorkspaceIfChanged()">Refresh approvals</button>`,'Quotation → approval → contract confirmation → advance → delivery → balance payment. Share documents manually.')+quotes.map(q=>{const p=related(q,'Proforma'),i=related(q,'Invoice'),s=stage(q),project=projectFor(q),sequential=q.contract?.deliveryMode==='sequential'||project?.deliveryMode==='sequential',deliveryComplete=!sequential||!!project&&(project.tasks||[]).every(task=>task.done);return `<section class="panel"><h2>${esc(q.client?.name||'Client')} · ${esc(q.project||q.number)}</h2><p>${names.map((n,k)=>`<span class="badge ${k===s?'Paid':''}">${k+1}. ${n}</span>`).join(' → ')}</p><h3>Quotation ${esc(q.number)}</h3><div class="actions">${docActions(q)}${q.status==='Draft'?`<button onclick="processMarkSent('${q.id}')">Mark quotation sent</button>`:''}${q.status==='Sent'?`<button onclick="processRecordApproval('${q.id}')">Record quotation approval</button>`:''}</div>${q.status==='Accepted'?'<p>Quotation approval received.</p>':''}${q.status==='Accepted'&&!q.contractConfirmedAt?`<div class="actions"><button class="primary" onclick="processContract('${q.id}')">Set up delivery & complete contract</button><button onclick="processContract('${q.id}','service-wise')">Set up with separate service invoices</button></div><p class="hint">Choose separate service invoices to create one proforma per service, then prepare each balance invoice as that service is completed.</p>`:''}${q.contractConfirmedAt?`<p><b>Contract confirmed</b> · ${esc(q.contract?.acceptedBy||'Client')} · ${esc(q.contract?.startDate||'Start date to be agreed')} · ${q.contract?.deliveryMode==='sequential'?'Services delivered one by one':'Services delivered together'}</p><div class="actions"><button class="primary" onclick="processProject('${q.id}')">${project?'Open project & assign work':'Create project & assign work'}</button></div><p class="hint">A delivery task is created for each quoted service. Assign a team member and mark the task complete in the project work plan.</p>`:''}${q.billingMode==='service-wise'&&q.contractConfirmedAt?serviceBilling(q,project):p&&q.billingMode!=='service-wise'?`<h3>Proforma ${esc(p.number)} · 50% advance ${esc(fmt(p,totals(p).total))}</h3><div class="actions">${docActions(p)}</div>${receiptActions(p)}${s===5&&!i&&deliveryComplete?`<button class="primary" onclick="processComplete('${q.id}')">Work complete — prepare final invoice</button>`:''}${i?`<h3>Final invoice ${esc(i.number)} · Balance ${esc(fmt(i,totals(i).balance))}</h3><div class="actions">${docActions(i)}</div>${receiptActions({...i,payments:i.payments})}`:''}`:''}${s===5&&!i&&!deliveryComplete&&q.billingMode!=='service-wise'?'<p class="hint">Complete each service in the project work plan to prepare the final invoice.</p>':''}${!q.contractConfirmedAt&&q.status==='Accepted'&&p?'<p class="hint">A proforma is already linked to this quotation; use the existing project-wide billing flow.</p>':''}</section>`}).join('')+(quotes.length?'':'<section class="panel">Create a quotation to begin a client process.</section>');};
window.processMarkSent=id=>{commitChange(()=>{find(id).status='Sent';find(id).updated=new Date().toISOString()},'Quotation marked sent. Record approval after the client accepts it.');};
window.processRecordApproval=id=>{commitChange(()=>{const q=find(id);q.status='Accepted';q.clientApprovedForProcess=true;q.acceptedAt=new Date().toISOString();q.updated=q.acceptedAt},'Quotation approval recorded. Complete the contract confirmation next.');};
window.processContract=(id,requestedBillingMode)=>{const q=find(id);if(!q||q.status!=='Accepted')return toast('Record quotation approval first.');const hasCombined=!!db.documents.find(d=>d.type==='Proforma'&&d.rootId===q.id&&d.status!=='Cancelled'&&d.serviceIndex===undefined),billingMode=hasCombined?'project':requestedBillingMode||q.billingMode||'project';modal('Contract confirmation',`<div class="full"><label>Client / authorised signatory<input id="contractAcceptedBy" required value="${esc(q.client?.name||'')}"></label></div><div><label>Contract start date<input id="contractStart" type="date" required value="${esc(q.contract?.startDate||new Date().toISOString().slice(0,10))}"></label></div><div><label>Expected completion date<input id="contractCompletion" type="date" value="${esc(q.contract?.completionDate||'')}"></label></div><div class="full"><label>Confirmed scope / notes<textarea id="contractScope" required>${esc(q.contract?.scope||q.project||'Services as quoted')}</textarea></label></div><div class="full"><label>How should we deliver the quoted services?<select id="contractDeliveryMode"><option value="parallel" ${q.contract?.deliveryMode!=='sequential'?'selected':''}>All services together — work can happen in parallel</option><option value="sequential" ${q.contract?.deliveryMode==='sequential'?'selected':''}>One service at a time — next service starts after the previous one is complete</option></select><small class="hint">This controls the order of delivery tasks in the project work plan.</small></label></div><div class="full"><label>How should we bill the services?<select id="contractBillingMode" ${hasCombined?'disabled':''}><option value="project" ${billingMode==='service-wise'?'':'selected'}>One proforma and one final invoice for the full quotation</option><option value="service-wise" ${billingMode==='service-wise'?'selected':''}>Separate proforma and balance invoice for every service</option></select><small class="hint">Service-wise billing creates a separate 50% advance request for each service. The matching advance is carried into that service’s balance invoice.</small></label></div>${hasCombined?'<p class="hint full">A combined proforma already exists. Keep project-wide billing for this quotation to avoid duplicate payment requests.</p>':''}<div class="full"><label><input id="contractConfirmation" type="checkbox" required> I confirm the agreed scope, dates, and advance requirement.</label></div>`,()=>{const acceptedBy=document.getElementById('contractAcceptedBy').value.trim(),startDate=document.getElementById('contractStart').value,completionDate=document.getElementById('contractCompletion').value,scope=document.getElementById('contractScope').value.trim(),deliveryMode=document.getElementById('contractDeliveryMode').value,billingMode=hasCombined?'project':document.getElementById('contractBillingMode').value;if(!acceptedBy||!startDate||!scope)return;let count=0;if(commitChange(()=>{q.contract={acceptedBy,startDate,completionDate,scope,deliveryMode,billingMode};q.billingMode=billingMode;q.contractConfirmedAt=new Date().toISOString();q.updated=q.contractConfirmedAt;if(billingMode==='service-wise')count=ClientProcessEngine.prepareServiceProformas(db,q,uid).length;else ClientProcessEngine.prepare(db,q,uid)},billingMode==='service-wise'?'Contract confirmed and separate service proformas created.':'Contract confirmed and project proforma created.')){closeRecord();nav('Client Process');if(billingMode==='service-wise')toast(`${count||serviceProformas(q).length} separate service proforma${(count||serviceProformas(q).length)===1?'':'s'} ready.`)}});};
window.processComplete=id=>{const q=find(id),p=related(q,'Proforma'),project=projectFor(q);if(!p||totals(p).paid<totals(p).total)return toast('Record the 50% advance first.');if((q.contract?.deliveryMode==='sequential'||project?.deliveryMode==='sequential')&&(!project||(project.tasks||[]).some(task=>!task.done)))return toast('Complete each service in order in the project work plan before preparing the final invoice.');if(related(q,'Invoice'))return openDoc(related(q,'Invoice').id);openDoc(p.id);convertTo('Invoice');if(draft?.type==='Invoice'&&saveDoc(true)){q.workCompletedAt=new Date().toISOString();persist();draft=null;nav('Client Process');}};
window.processShare=async(id,channel,index)=>{const d=find(id);if(!d)return;try{const receipt=Number.isInteger(index),payment=receipt?d.payments[index]:null;const file=receipt?await createPaymentReceiptPdf({...d,payments:[payment],number:d.number+'-R'+(index+1)}):await createDocumentPdf(d);downloadPdfFile(file);if(channel==='download')return;const title=(receipt?'Payment receipt':docLabel(d.type))+' '+d.number;const message=title+' for '+(d.client?.name||'your project')+'. Please find the PDF attached.';if(channel==='whatsapp'){let phone=String(d.client?.phone||'').replace(/\D/g,'');if(phone.length===10)phone='91'+phone;window.open('https://wa.me/'+phone+'?text='+encodeURIComponent(message),'_blank','noopener');}else{location.href='mailto:'+encodeURIComponent(d.client?.email||'')+'?subject='+encodeURIComponent(title)+'&body='+encodeURIComponent(message);}toast('PDF downloaded. Attach it to the message and send manually.');}catch(e){toast(e.message||'Could not prepare the document.')}};
HORIZONTAL_MORE_SECTIONS.push('Client Process');HORIZONTAL_MORE_GROUPS[1].items.push('Client Process');
const previous=render;render=function(){previous();if(view==='Client Process'&&!draft)document.getElementById('app').innerHTML=clientProcessPage();const navEl=document.getElementById('nav');if(navEl&&!navEl.querySelector('[data-client-process]')){const button=document.createElement('button');button.dataset.clientProcess='1';button.textContent='Client Process';button.onclick=()=>nav('Client Process');navEl.append(button);}};
document.addEventListener('erp-workspace-loaded',()=>{if(!draft)reconcile()});
})();
